sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Título da caixa */
.info-title {
    background-color: #e0e0e0;
    color: #000;
    padding: 8px 12px;
    border-radius: 4px 4px 0 0;
    margin: 16px 0 0 0;
    font-size: 18px;
    //font-weight: bold;
   font-family: 'Roboto Flex', sans-serif;
}

/* Caixa de informações */
.info-box {
   font-family: 'Roboto Flex', sans-serif;
    border: 1px solid #ccc;
    padding: 10px 14px;
    background-color: #f9f9f9;
    border-radius: 0 0 4px 4px;
    margin: 0;
    font-size: 13px;
    color: #333;
    line-height: 1.4;
    max-width: 100%;
    box-sizing: border-box;
}

.info-box p {
    margin: 4px 0;
}

/* Títulos internos */
.info-box strong {
   font-family: 'Roboto Flex', sans-serif;
    display: block;
    margin-bottom: 2px;
    color: #000;
    font-size: 14px;
}

/* Destaques */
.info-box .sub-info {
   font-family: 'Roboto Flex', sans-serif;
    color: #0066cc;
    font-weight: 500;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  .info-title {
    font-size: 1rem;
    padding: 6px 10px;
    margin-top: 1rem;
  }
  .info-box {
    font-size: 0.85rem;
    padding: 8px 10px;
    line-height: 1.3;
  }
  .info-box strong {
    font-size: 0.9rem;
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  .info-title {
    font-size: 1.05rem;
    margin-top: 1.2rem;
  }
  .info-box {
    font-size: 0.9rem;
  }
  .info-box strong {
    font-size: 0.95rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  .info-title {
    font-size: 18px; /* Valor original */
    margin: 16px 0 0 0; /* Valor original */
  }
  .info-box {
    font-size: 13px; /* Valor original */
  }
  .info-box strong {
    font-size: 14px; /* Valor original */
  }
}

/* Ajustes específicos para dispositivos muito largos como Nest Hub Max ou telas 4K */
@media (min-width: 1280px) {
    .info-title {
        padding: 10px 14px;
    }
    .info-box {
        padding: 12px 16px;
    }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    .info-title {
        font-size: 1rem;
        margin-top: 1.1rem;
    }
    .info-box {
        font-size: 0.87rem;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    .info-title {
        font-size: 0.9rem;
    }
    .info-box {
        font-size: 0.8rem;
    }
    .info-box strong {
        font-size: 0.85rem;
    }
}
